insert into public.software (name, slug, tagline, description_short, description_full, logo_url, category_id, starting_price, price_currency, billing_period, price_is_net, price_unit, free_trial, trial_days, free_version, free_demo, pricing_plans, pricing_note, features, top_features, integrations, pros, cons, ideal_for, brand_color, gobd_compliant, datev_interface, e_invoicing, elster_submission, hosting_location, dpa_available, iso27001, tse_certified, skr_support, german_support, vendor_country, compliance_checked_at, affiliate_url, vendor_website, affiliate_network, vendor_name, founded_year, vendor_hq, support_types, countries_available, languages, editorial_rating, editorial_ease, editorial_value, editorial_service, editorial_functionality, editorial_verdict, editorial_review, editorial_author, editorial_tested_at, status, featured) values
('Kenjo', 'kenjo', 'HR-Software für Unternehmen mit gewerblichen Mitarbeitenden', 'HR-Software aus Berlin mit Fokus auf Schichtbetrieb, Zeiterfassung und mobile Mitarbeitende.', '<p>Kenjo legt einen Schwerpunkt auf Unternehmen mit gewerblichen oder mobilen Mitarbeitenden, etwa in Produktion, Logistik oder Gastronomie. Zeiterfassung, Schichtplanung und Abwesenheiten laufen über eine mobile App.</p><p>Personalakte, Onboarding und Lohnvorbereitung ergänzen die Plattform.</p>', null, (select id from public.categories where slug = 'hr-software'), null, 'EUR', 'month', true, 'employee', true, 14, false, true, '[]'::jsonb, null, '["Digitale Personalakte","Abwesenheitsmanagement","Onboarding","Zeiterfassung","Vorbereitende Lohnabrechnung","Mitarbeiter-App"]'::jsonb, '["Fokus auf gewerbliche Mitarbeitende","Schichtplanung","Mobile App"]'::jsonb, '["DATEV","Slack","Microsoft Teams"]'::jsonb, '["Gute App für Mitarbeitende ohne Schreibtisch","Schichtplanung integriert"]'::jsonb, '["Recruiting weniger ausgebaut","Preis nur auf Anfrage"]'::jsonb, 'Betriebe mit Schichtarbeit und mobilen Teams.', null, null, 'export', '[]'::jsonb, null, 'EU', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.kenjo.io/de', 'keins', 'Kenjo GmbH', 2015, 'Berlin', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4, 4.3, 3.9, 4, 4.1, 'Kenjo ist auf Unternehmen mit gewerblichen und mobilen Beschäftigten ausgerichtet. Zeiterfassung, Schichtplanung und Abwesenheiten per App stehen im Mittelpunkt.', '<h3>Die Ausrichtung</h3><p>Viele HR-Tools sind für Büroangestellte gedacht. Kenjo richtet sich ausdrücklich an Betriebe in Produktion, Logistik, Einzelhandel und Gastronomie, wo Beschäftigte keinen festen Rechner haben und über das Smartphone arbeiten.</p><h3>Funktionen</h3><p>Stempeln per App oder Terminal, Schichtpläne, Abwesenheiten und Dokumente bilden den Kern. In den größeren Plänen kommen digitale Signaturen, On- und Offboarding, Standortverwaltung und ein Hinweisgebersystem hinzu.</p><h3>Kosten und Test</h3><p>Der Preis richtet sich nach Plan und Mitarbeiterzahl, bei jährlicher Zahlung gibt es zehn Prozent Rabatt. Eine kostenlose Testphase dauert 14 Tage, für den größten Plan gibt es eine Demo.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('softgarden', 'softgarden', 'Bewerbermanagement und Recruiting', 'Recruiting-Software aus Berlin für Stellenausschreibung, Bewerbermanagement und Talent-Pools.', '<p>softgarden ist auf Recruiting spezialisiert: Stellen werden mit einem Klick auf Jobbörsen veröffentlicht, Bewerbungen strukturiert bewertet und Kandidaten DSGVO-konform in Talent-Pools verwaltet.</p><p>Eine Schnittstelle zu gängigen HR-Systemen übernimmt eingestellte Kandidaten in die Personalakte.</p>', null, (select id from public.categories where slug = 'hr-software'), null, 'EUR', 'month', true, 'account', false, null, false, true, '[]'::jsonb, null, '["Recruiting & Bewerbermanagement","Onboarding","Rollen & Rechte"]'::jsonb, '["Multiposting auf Jobbörsen","DSGVO-konforme Talent-Pools","Bewerberfreundlicher Prozess"]'::jsonb, '["Personio","StepStone","Indeed","LinkedIn","XING"]'::jsonb, '["Sehr gutes Bewerbererlebnis","Starke Jobbörsen-Anbindung"]'::jsonb, '["Nur Recruiting, keine Voll-HR","Preis nur auf Anfrage"]'::jsonb, 'Unternehmen mit regelmäßigem Personalbedarf.', null, null, null, '[]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://softgarden.com/de/', 'keins', 'softgarden e-recruiting GmbH', 2003, 'Berlin', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.2, 4.3, 4, 4.2, 4.3, 'softgarden ist eine spezialisierte Recruiting-Software aus Berlin. Wer viele Stellen besetzt und Bewerbende gut erreichen will, bekommt hier ein sehr durchdachtes Werkzeug.', '<h3>Worauf softgarden spezialisiert ist</h3><p>softgarden ist keine vollständige HR-Suite, sondern konzentriert sich auf das Recruiting. Stellen werden mit wenigen Klicks auf Jobbörsen veröffentlicht, Bewerbungen strukturiert gesammelt und im Team bewertet.</p><h3>Stärken</h3><p>Die Bewerbung selbst ist kurz und mobil möglich, was die Zahl abgebrochener Bewerbungen senkt. Für Personalabteilungen bieten Bewertungsbögen, Vorlagen und Auswertungen einen guten Überblick über den Stand jeder Stelle.</p><h3>Kosten</h3><p>Preise gibt es auf Anfrage, sie richten sich nach der Zahl der Stellen und Nutzer. Eine Demo ist kostenlos.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('HubSpot', 'hubspot', 'CRM-Plattform für Marketing, Vertrieb und Service', 'CRM mit kostenloser Einstiegsversion und optionalen Hubs für Marketing, Vertrieb, Service und Content.', '<p>HubSpot bietet ein kostenloses CRM als Basis, das sich um kostenpflichtige Hubs für Marketing, Vertrieb, Kundenservice und Content erweitern lässt. Die Stärke liegt in der Kombination von Marketing-Automation und Vertriebspipeline.</p><p>Für europäische Kunden steht ein Rechenzentrum in der EU zur Verfügung; ein Auftragsverarbeitungsvertrag ist verfügbar.</p>', null, (select id from public.categories where slug = 'crm-software'), 0, 'EUR', 'month', true, 'user', true, null, true, true, '[{"name":"Free","price":0,"period":"month","unit":"user","features":["Bis zu 2 Nutzer"]},{"name":"Starter","price":20,"period":"month","unit":"user","features":["jährlich ab 7 € je Lizenz"]},{"name":"Professional","price":100,"period":"month","unit":"user","features":["einmalige Onboarding-Gebühr 1.470 €"],"highlighted":true},{"name":"Enterprise","price":150,"period":"month","unit":"user","features":["einmalige Onboarding-Gebühr 3.420 €"]}]'::jsonb, null, '["Kontakt- & Firmenverwaltung","Vertriebspipeline","Angebotserstellung","E-Mail-Integration","Marketing-Automation","Aufgaben & Wiedervorlagen","Berichte & Dashboards","Double-Opt-in-Verwaltung","Mobile App","Telefonie-Integration"]'::jsonb, '["Kostenloses CRM","Marketing und Vertrieb in einer Plattform","EU-Rechenzentrum"]'::jsonb, '["Outlook","Gmail","Slack","Zoom","WordPress","Shopify","sevdesk"]'::jsonb, '["Kostenloser Einstieg","Sehr umfangreiches Ökosystem","Gute Bedienbarkeit"]'::jsonb, '["Professional-Tarife schnell teuer","US-Anbieter trotz EU-Hosting"]'::jsonb, 'Wachsende Unternehmen mit Inbound-Marketing.', null, null, null, '[]'::jsonb, null, 'EU', true, null, null, '[]'::jsonb, true, 'USA', '2026-09-22', null, 'https://www.hubspot.de/', 'keins', 'HubSpot, Inc.', 2006, 'Cambridge (USA), DE-Büro Berlin', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch","Französisch","Spanisch"]'::jsonb, 4.4, 4.5, 4, 4.1, 4.7, 'HubSpot bietet den großzügigsten kostenlosen Einstieg aller CRM-Systeme und wächst bis in die Enterprise-Liga mit. Ab dem Tarif Professional werden die Kosten allerdings schnell erheblich.', '<h3>Der Einstieg</h3><p>Das kostenlose CRM erlaubt bis zu zwei Nutzer und enthält Kontakte, Unternehmen, Deals und eine Pipeline. Für Gründer und kleine Teams ist das ein echter Mehrwert, und viele bleiben lange in dieser Stufe.</p><h3>Stärken</h3><p>HubSpot verbindet Vertrieb, Marketing und Service auf einer Datenbasis. E-Mails, Anrufe und Meetings landen automatisch am Kontakt, und die Oberfläche ist so aufgeräumt, dass auch vertriebsferne Kolleginnen sie nutzen. Der Marktplatz bietet Anbindungen an nahezu jedes gängige Werkzeug.</p><h3>Die Kostenfrage</h3><p>Der Sales Hub Starter kostet 20 € je Lizenz im Monat, bei jährlicher Zahlung ab 7 €. Professional liegt bei 100 € je Lizenz und verlangt eine einmalige Onboarding-Gebühr von 1.470 €. Enterprise kostet 150 € je Lizenz plus 3.420 € Onboarding. Für ein Team von zehn Personen im Professional-Tarif kommen so schnell über 13.000 € im ersten Jahr zusammen.</p><h3>Datenschutz</h3><p>HubSpot ist ein US-Anbieter, bietet aber eine Datenhaltung in der EU und einen Auftragsverarbeitungsvertrag an. Klären Sie die Einstellungen vor dem Import Ihrer Kundendaten mit Ihrer Datenschutzbeauftragten.</p>', 'Nadeem Abbas', '2026-09-22', 'published', true),
('Salesforce', 'salesforce', 'Das CRM für komplexe Vertriebsorganisationen', 'Hoch anpassbares CRM für mittlere und große Vertriebsorganisationen mit umfangreichem Ökosystem.', '<p>Salesforce Sales Cloud ist das weltweit verbreitetste CRM für Vertriebsorganisationen. Es lässt sich nahezu beliebig anpassen und über den AppExchange erweitern.</p><p>Mit der Hyperforce-Infrastruktur ist eine Datenhaltung in der EU möglich. Für kleinere Teams gibt es die Starter Suite.</p>', null, (select id from public.categories where slug = 'crm-software'), 25, 'EUR', 'month', true, 'user', true, null, false, true, '[{"name":"Starter Suite","price":25,"period":"month","unit":"user","features":[]},{"name":"Pro Suite","price":100,"period":"month","unit":"user","features":[],"highlighted":true},{"name":"Core","price":195,"period":"month","unit":"user","features":[]},{"name":"Advanced","price":395,"period":"month","unit":"user","features":[]}]'::jsonb, null, '["Kontakt- & Firmenverwaltung","Vertriebspipeline","Angebotserstellung","E-Mail-Integration","Marketing-Automation","Aufgaben & Wiedervorlagen","Berichte & Dashboards","Mobile App","Telefonie-Integration"]'::jsonb, '["Nahezu unbegrenzt anpassbar","AppExchange-Ökosystem","Forecasting auf Enterprise-Niveau"]'::jsonb, '["Outlook","Gmail","Slack","SAP","DocuSign","LinkedIn"]'::jsonb, '["Maximale Flexibilität","Skaliert bis zum Konzern"]'::jsonb, '["Teuer in höheren Editionen","Einführung meist mit Partner"]'::jsonb, 'Mittelgroße und große Vertriebsorganisationen.', null, null, null, '[]'::jsonb, null, 'EU', true, true, null, '[]'::jsonb, true, 'USA', '2026-09-22', null, 'https://www.salesforce.com/de/', 'keins', 'Salesforce, Inc.', 1999, 'San Francisco (USA), DE-Büro München', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch","und weitere"]'::jsonb, 4.3, 3.8, 3.8, 4.1, 4.9, 'Salesforce ist das mächtigste CRM am Markt und lässt sich an fast jeden Vertriebsprozess anpassen. Für kleine Teams ist es meist zu groß, für wachsende Vertriebsorganisationen oft alternativlos.', '<h3>Einordnung</h3><p>Salesforce setzt seit Jahren den Maßstab für Vertriebssoftware. Pipelines, Prognosen, Gebietsmanagement, Angebote und Berichte lassen sich tief anpassen, und die Plattform wächst mit Unternehmen bis in Konzerngröße.</p><h3>Preise</h3><p>Die Starter Suite kostet 25 € je Nutzer im Monat, die Pro Suite 100 €. Darüber liegen Core für 195 €, Advanced für 395 € und Max für 550 € je Nutzer, jeweils bei jährlicher Zahlung. Hinzu kommen in der Praxis häufig Kosten für Implementierungspartner.</p><h3>Für wen es passt</h3><p>Die Starter Suite ist ein ordentlicher Einstieg für kleine Teams, die später wachsen wollen. Richtig spielt Salesforce seine Stärken aus, wenn mehrere Vertriebsteams, komplexe Freigaben und viele Integrationen zusammenkommen. Eine kostenlose Testphase wird für die kleineren Editionen angeboten.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Pipedrive', 'pipedrive', 'Pipeline-CRM für Vertriebsteams', 'Visuelles Pipeline-CRM, das Vertriebsteams auf die nächsten Schritte fokussiert.', '<p>Pipedrive stellt die Vertriebspipeline in den Mittelpunkt: Deals werden per Drag-and-drop durch Phasen bewegt, Aktivitäten erinnern an nächste Schritte. Das CRM ist schnell eingerichtet und besonders bei kleinen Vertriebsteams beliebt.</p><p>Die Daten europäischer Kunden werden in der EU gespeichert.</p>', null, (select id from public.categories where slug = 'crm-software'), 14, 'EUR', 'month', true, 'user', true, 14, false, false, '[{"name":"Lite","price":14,"period":"month","unit":"user","features":[]},{"name":"Growth","price":24,"period":"month","unit":"user","features":[]},{"name":"Premium","price":49,"period":"month","unit":"user","features":[],"highlighted":true},{"name":"Ultimate","price":69,"period":"month","unit":"user","features":[]}]'::jsonb, null, '["Kontakt- & Firmenverwaltung","Vertriebspipeline","Angebotserstellung","E-Mail-Integration","Aufgaben & Wiedervorlagen","Berichte & Dashboards","Mobile App","Telefonie-Integration"]'::jsonb, '["Visuelle Pipeline","Aktivitätsbasiertes Verkaufen","Schnelle Einrichtung"]'::jsonb, '["Outlook","Gmail","Slack","Zapier","Lexware Office","sevdesk"]'::jsonb, '["Sehr intuitiv","Günstiger Einstieg"]'::jsonb, '["Marketing-Funktionen begrenzt","Berichte in kleinen Tarifen eingeschränkt"]'::jsonb, 'Kleine und mittlere Vertriebsteams.', null, null, null, '[]'::jsonb, null, 'EU', true, true, null, '[]'::jsonb, true, 'Estland', '2026-09-22', null, 'https://www.pipedrive.com/de', 'keins', 'Pipedrive OÜ', 2010, 'Tallinn (Estland)', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.4, 4.7, 4.3, 4, 4.1, 'Pipedrive ist das CRM für Vertriebsteams, die vor allem ihre Pipeline im Blick behalten wollen. Klar, schnell und mit fairen Preisen ab 14 € je Nutzer.', '<h3>Das Prinzip</h3><p>Pipedrive stellt die Verkaufschance in den Mittelpunkt. Deals wandern per Ziehen und Ablegen durch die Phasen, und die Software erinnert daran, was als Nächstes zu tun ist. Wer aus Excel oder einem überladenen CRM kommt, ist in wenigen Stunden arbeitsfähig.</p><h3>Preise</h3><p>Lite kostet 14 €, Growth 24 €, Premium 49 € und Ultimate 69 € je Nutzer im Monat. Alle Tarife lassen sich 14 Tage kostenlos testen, ohne Kreditkarte.</p><h3>Grenzen</h3><p>Marketing- und Serviceprozesse deckt Pipedrive nur in Ansätzen ab. Wer ein System für den gesamten Kundenlebenszyklus sucht, sollte HubSpot vergleichen. Für reine Vertriebsteams ist Pipedrive aber eine der besten Lösungen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Zoho CRM', 'zoho-crm', 'Preiswertes CRM mit großem Funktionsumfang', 'Umfangreiches CRM mit kostenloser Version für bis zu drei Nutzer und EU-Rechenzentrum.', '<p>Zoho CRM bietet einen großen Funktionsumfang zu vergleichsweise niedrigen Preisen und ist Teil der Zoho-Suite mit über 50 Anwendungen. Für kleine Teams gibt es eine kostenlose Version.</p><p>Europäische Kunden werden aus einem EU-Rechenzentrum bedient.</p>', null, (select id from public.categories where slug = 'crm-software'), 14, 'EUR', 'month', true, 'user', true, null, true, true, '[]'::jsonb, 'kostenlose Edition für bis zu 3 Nutzer', '["Kontakt- & Firmenverwaltung","Vertriebspipeline","Angebotserstellung","E-Mail-Integration","Marketing-Automation","Aufgaben & Wiedervorlagen","Berichte & Dashboards","Mobile App","Telefonie-Integration"]'::jsonb, '["Kostenlose Version","Teil der Zoho-Suite","Günstige Tarife"]'::jsonb, '["Zoho Books","Outlook","Gmail","Slack","Zapier"]'::jsonb, '["Gutes Preis-Leistungs-Verhältnis","Sehr viele Funktionen"]'::jsonb, '["Oberfläche teils überladen","Deutsche Übersetzung nicht immer sauber"]'::jsonb, 'Preisbewusste KMU mit breiten Anforderungen.', null, null, null, '[]'::jsonb, null, 'EU', true, null, null, '[]'::jsonb, true, 'Indien', '2026-09-22', null, 'https://www.zoho.com/de/crm/', 'keins', 'Zoho Corporation', 1996, 'Chennai (Indien), EU-Sitz Utrecht', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.1, 3.9, 4.5, 3.8, 4.4, 'Zoho CRM bietet viel Funktion für wenig Geld und eine kostenlose Edition für bis zu drei Nutzer. Die Einarbeitung ist etwas aufwendiger als bei Pipedrive.', '<h3>Was Zoho bietet</h3><p>Zoho CRM ist Teil einer großen Produktfamilie mit Buchhaltung, Helpdesk, Umfragen und mehr. Workflows, Berechtigungen und Berichte lassen sich weitgehend anpassen, auch in den günstigeren Editionen.</p><h3>Preise und Test</h3><p>Die kostenlose Edition erlaubt bis zu drei Nutzer mit den wichtigsten Grundfunktionen. Die kostenpflichtigen Editionen Standard, Professional, Enterprise und Ultimate werden je Nutzer abgerechnet, eine kostenlose Testphase ist verfügbar. Die aktuellen Euro-Preise zeigt Zoho nach Auswahl der Währung auf der Preisseite an.</p><h3>Fazit</h3><p>Für preisbewusste Teams, die bereit sind, etwas Zeit in die Einrichtung zu stecken, ist Zoho CRM ein sehr gutes Angebot. Rechenzentren in der EU stehen zur Verfügung.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('CentralStationCRM', 'centralstationcrm', 'Einfaches CRM für kleine Teams aus Köln', 'Schlankes CRM aus Köln für kleine Teams, mit Serverstandort in Deutschland.', '<p>CentralStationCRM richtet sich an kleine Unternehmen, die ein unkompliziertes CRM ohne lange Einarbeitung suchen. Kontakte, Firmen, Angebote und Aufgaben werden übersichtlich verwaltet.</p><p>Die Daten liegen auf Servern in Deutschland. Für viele kleine Betriebe ist das ein entscheidendes Argument.</p>', null, (select id from public.categories where slug = 'crm-software'), 0, 'EUR', 'month', true, 'account', true, 30, true, false, '[{"name":"Starter","price":0,"period":"month","unit":"account","features":["3 Nutzer, 200 Kontakte"]},{"name":"Team","price":24,"period":"month","unit":"account","features":["3 Nutzer, 3.000 Kontakte"],"highlighted":true},{"name":"Small Office","price":75,"period":"month","unit":"account","features":["10 Nutzer, 10.000 Kontakte"]},{"name":"Business","price":149,"period":"month","unit":"account","features":["20 Nutzer, 20.000 Kontakte"]},{"name":"Enterprise","price":289,"period":"month","unit":"account","features":["40 Nutzer, 40.000 Kontakte"]}]'::jsonb, null, '["Kontakt- & Firmenverwaltung","Vertriebspipeline","Angebotserstellung","E-Mail-Integration","Aufgaben & Wiedervorlagen","Berichte & Dashboards","Double-Opt-in-Verwaltung","Mobile App"]'::jsonb, '["Serverstandort Deutschland","Sehr schnell eingerichtet","Fair für kleine Teams"]'::jsonb, '["Outlook","Gmail","Lexware Office","Zapier"]'::jsonb, '["Einfachheit","Deutscher Anbieter und Support"]'::jsonb, '["Wenig Automatisierung","Für größere Vertriebsteams zu schlank"]'::jsonb, 'Kleine Teams bis etwa 20 Personen.', null, null, null, '[]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://centralstationcrm.de/', 'keins', '44Pixels GmbH', null, 'Köln', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.3, 4.7, 4.3, 4.3, 3.7, 'CentralStationCRM aus Köln ist das CRM für kleine Teams, die es einfach und datenschutzfreundlich wollen. Server in Deutschland, klare Preise und eine kostenlose Version für bis zu drei Nutzer.', '<h3>Das Konzept</h3><p>Das Programm verzichtet bewusst auf Funktionsfülle. Kontakte, Firmen, Aufgaben, Angebote und Notizen stehen im Mittelpunkt, dazu eine Teamübersicht. Wer von Excel oder Outlook-Kontakten kommt, findet sich sofort zurecht.</p><h3>Preise</h3><p>Starter ist kostenlos für drei Nutzer und 200 Kontakte. Team kostet 24 € im Monat für drei Nutzer und 3.000 Kontakte, Small Office 75 € für zehn Nutzer, Business 149 € für 20 Nutzer und Enterprise 289 € für 40 Nutzer. Alle bezahlten Tarife haben den gleichen Funktionsumfang. Eine Testphase von 30 Tagen läuft ohne Zahlungsdaten und ohne Kündigung aus.</p><h3>Fazit</h3><p>Für Handwerksbetriebe, Agenturen und Dienstleister mit einem kleinen Vertriebsteam ist CentralStationCRM eine der sympathischsten Lösungen. Wer Automatisierung und Marketingfunktionen braucht, stößt an Grenzen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('CAS genesisWorld', 'cas-genesisworld', 'xRM für den Mittelstand', 'Umfassende CRM- und xRM-Lösung aus Karlsruhe, on-premise oder in der Cloud.', '<p>CAS genesisWorld ist ein etabliertes CRM des Karlsruher Anbieters CAS Software. Neben klassischen Vertriebsfunktionen bildet es als xRM-Lösung beliebige Beziehungen ab, etwa zu Lieferanten, Partnern oder Mitarbeitenden.</p><p>Die Lösung kann im eigenen Rechenzentrum oder als Cloud-Variante mit Hosting in Deutschland betrieben werden.</p>', null, (select id from public.categories where slug = 'crm-software'), null, 'EUR', 'month', true, 'user', false, null, false, true, '[]'::jsonb, null, '["Kontakt- & Firmenverwaltung","Vertriebspipeline","Angebotserstellung","E-Mail-Integration","Marketing-Automation","Aufgaben & Wiedervorlagen","Berichte & Dashboards","Double-Opt-in-Verwaltung","Mobile App","Telefonie-Integration"]'::jsonb, '["xRM-Flexibilität","On-Premise oder Cloud","Starker Partnerkanal"]'::jsonb, '["Outlook","SAP","DATEV","Microsoft Teams"]'::jsonb, '["Sehr anpassbar","Deutscher Anbieter mit langer Historie"]'::jsonb, '["Einführung über Partner","Oberfläche wirkt klassisch"]'::jsonb, 'Mittelständler mit komplexen Kundenbeziehungen.', null, null, null, '[]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.cas.de', 'keins', 'CAS Software AG', 1986, 'Karlsruhe', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.1, 3.7, 3.9, 4.3, 4.6, 'CAS genesisWorld aus Karlsruhe ist ein etabliertes xRM-System für den Mittelstand, das weit über den Vertrieb hinausgeht. Die Stärke ist die Anpassbarkeit, die Einführung braucht einen Partner.', '<h3>Einordnung</h3><p>genesisWorld verwaltet nicht nur Kunden, sondern beliebige Beziehungen, etwa zu Lieferanten, Partnern oder Mitarbeitenden. Viele mittelständische Unternehmen nutzen es als zentrale Kontaktdatenbank über Abteilungsgrenzen hinweg.</p><h3>Stärken</h3><p>Die Software kann im eigenen Rechenzentrum oder in der Cloud betrieben werden, die Integration in Microsoft Office ist tief. Ein großes Partnernetz in Deutschland übernimmt Einführung und Anpassung.</p><h3>Kosten</h3><p>Preise werden individuell über Partner kalkuliert. Eine Demo ist kostenlos.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false)
